using System.Windows;using System.Windows.Input;using OncaPDV.Application;using OncaPDV.Domain;
namespace OncaPDV.Desktop;public partial class CustomerSearchWindow:Window{private readonly CustomerService _service;private readonly bool _management;public CustomerProfile? Selected{get;private set;}public CustomerSearchWindow(CustomerService service,bool management=false){_service=service;_management=management;InitializeComponent();SelectButton.Visibility=management?Visibility.Collapsed:Visibility.Visible;Loaded+=async(_,_)=>await Search();}private async Task Search()=>Grid.ItemsSource=await _service.SearchAsync(Query.Text.Trim(),true);private async void Search_Click(object s,RoutedEventArgs e)=>await Search();private async void Query_KeyDown(object s,KeyEventArgs e){if(e.Key==Key.Enter)await Search();}private async void New_Click(object s,RoutedEventArgs e){var w=new CustomerEditWindow{Owner=this};if(w.ShowDialog()==true){await _service.SaveAsync(w.Customer!);Selected=w.Customer;if(_management)await Search();else DialogResult=true;}}private async void Edit_Click(object s,RoutedEventArgs e){if(Grid.SelectedItem is not CustomerProfile c)return;var w=new CustomerEditWindow(c){Owner=this};if(w.ShowDialog()==true){await _service.SaveAsync(w.Customer!);await Search();}}private async void Toggle_Click(object s,RoutedEventArgs e){if(Grid.SelectedItem is not CustomerProfile c)return;await _service.SaveAsync(c with{Active=!c.Active});await Search();}private void History_Click(object s,RoutedEventArgs e){if(Grid.SelectedItem is CustomerProfile c)new CustomerHistoryWindow(c){Owner=this}.ShowDialog();}private void Credit_Click(object s,RoutedEventArgs e){if(Grid.SelectedItem is CustomerProfile c)new CreditWindow(AppServices.Database,c.Id,true){Owner=this}.ShowDialog();}private void Select_Click(object s,RoutedEventArgs e){if(Grid.SelectedItem is CustomerProfile c&&c.Active){Selected=c;DialogResult=true;}}}
